// The supplied form handler. Do not edit this file.
// saveProfile(fields) takes { displayName, bio } and returns a promise that
// resolves with { ok: true } or { ok: false, message }.
function saveProfile(fields) {
  if (typeof fields.displayName !== 'string' || fields.displayName.trim() === '') {
    return Promise.resolve({ ok: false, message: 'Display name is required.' });
  }
  const saved = { displayName: fields.displayName.trim(), bio: String(fields.bio || '') };
  window.localStorage.setItem('profile', JSON.stringify(saved));
  return Promise.resolve({ ok: true });
}

window.saveProfile = saveProfile;
